CREATE OR REPLACE FUNCTION public.touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_device_code()
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ';
  candidate text;
begin
  candidate :=
    substr(alphabet, 1 + floor(random() * length(alphabet))::int, 1) ||
    substr(alphabet, 1 + floor(random() * length(alphabet))::int, 1);

  return candidate;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.normalize_item_text(input text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select trim(
    regexp_replace(
      lower(
        replace(
          replace(
            replace(
              coalesce(input, ''),
              'mm²', 'sqmm'
            ),
            'mm2', 'sqmm'
          ),
          '&', 'and'
        )
      ),
      '\s+',
      ' ',
      'g'
    )
  );
$function$
;

CREATE OR REPLACE FUNCTION public.set_row_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.stamp_row_ownership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'INSERT' then
    if new.created_by is null then
      new.created_by = auth.uid();
    end if;

    if new.updated_by is null then
      new.updated_by = coalesce(new.created_by, auth.uid());
    end if;

    if new.created_at is null then
      new.created_at = now();
    end if;

    if new.updated_at is null then
      new.updated_at = now();
    end if;
  elsif tg_op = 'UPDATE' then
    new.updated_by = coalesce(auth.uid(), new.updated_by);
    new.updated_at = now();
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.admin_update_device_assignment_code(p_assignment_id uuid, p_device_code text)
 RETURNS device_installations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  normalized_code text := upper(btrim(coalesce(p_device_code, '')));
  updated_row public.device_installations;
  requester_is_admin boolean := false;
begin
  -- EDIT THIS LINE if your admin flag/role field is different
  select coalesce(p.is_admin, false)
  into requester_is_admin
  from public.profiles p
  where p.id = auth.uid();

  if not coalesce(requester_is_admin, false) then
    raise exception 'Only admins can update device assignment codes';
  end if;

  if normalized_code !~ '^[A-Z]{2}$' then
    raise exception 'device code must be exactly two uppercase letters';
  end if;

  update public.device_installations di
  set
    device_code = normalized_code,
    assigned_automatically = false,
    assigned_by = auth.uid(),
    updated_at = now()
  where di.id = p_assignment_id
    and di.active = true
    and not exists (
      select 1
      from public.device_installations other
      where other.device_code = normalized_code
        and other.active = true
        and other.id <> di.id
    )
  returning * into updated_row;

  if not found then
    if exists (
      select 1
      from public.device_installations other
      where other.device_code = normalized_code
        and other.active = true
        and other.id <> p_assignment_id
    ) then
      raise exception 'device code is already assigned to another active installation';
    end if;

    raise exception 'active device assignment not found';
  end if;

  return updated_row;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.admin_revoke_device_assignment(p_assignment_id uuid)
 RETURNS device_installations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  updated_row public.device_installations;
  requester_is_admin boolean := false;
begin
  -- EDIT THIS LINE if your admin flag/role field is different
  select coalesce(p.is_admin, false)
  into requester_is_admin
  from public.profiles p
  where p.id = auth.uid();

  if not coalesce(requester_is_admin, false) then
    raise exception 'Only admins can revoke device assignments';
  end if;

  update public.device_installations
  set
    active = false,
    revoked_at = now(),
    updated_at = now()
  where id = p_assignment_id
    and active = true
  returning * into updated_row;

  if not found then
    raise exception 'active device assignment not found';
  end if;

  return updated_row;
end;
$function$
;

